const assignedId = $json.assigned_lawyer_id;

let lawyerName = null;

if (assignedId === 'YOUR_GHL_USER_ID_4') {
  lawyerName = 'Miss Rodriguez';
} else if (assignedId === 'YOUR_GHL_USER_ID_2') {
  lawyerName = 'Mister Martinez';
} else if (assignedId === 'YOUR_GHL_USER_ID_3') {
  lawyerName = 'Miss Rachel';
}

return [
  {
    json: {
      ...$json,
      lawyer_name: lawyerName
    }
  }
];

